// w11-ex01_05-pointer-03.c
#include<stdio.h>

int main() {
    int a1 = 100;
    int* a2 = &a1;
    int a3 = a1;

    a3 = 1000;
    printf("a1: %d\n", a1);
    printf("a3: %d\n", a3);

    *a2 = 2000;
    printf("a1: %d\n", a1);
    printf("*a2: %d\n", *a2);

    return 0;
}

